#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXW 256
#define MAXH 256
#define INF 1000000000

typedef struct {
    int x, y;
} Point;

static int W, H;
static char grid[MAXH][MAXW + 5];
static int dista[MAXH][MAXW];
static int owner[MAXH][MAXW];   /* -2: blocked, -1: tie/no owner, >=0 store id */
static int candId[MAXH][MAXW];  /* candidate index for empty cells, else -1 */

static Point stores[MAXW * MAXH];
static Point cands[MAXW * MAXH];
static int scnt, ccnt;

/* odd-r horizontal layout */
static const int dx_even[6] = {-1, 1, -1, 0, -1, 0};
static const int dy_even[6] = { 0, 0, -1,-1,  1, 1};
static const int dx_odd [6] = {-1, 1,  0, 1,  0, 1};
static const int dy_odd [6] = { 0, 0, -1,-1,  1, 1};

static int qx[MAXW * MAXH * 2];
static int qy[MAXW * MAXH * 2];
static int qid[MAXW * MAXH * 2];

static int inb(int x, int y) {
    return 0 <= x && x < W && 0 <= y && y < H;
}

int main(void) {
    if (scanf("%d %d", &H, &W) != 2) return 0;

    for (int y = 0; y < H; y++) {
        scanf("%s", grid[y]);
    }

    scnt = 0;
    ccnt = 0;
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            candId[y][x] = -1;
            if (grid[y][x] == '#') {
                owner[y][x] = -2;
                dista[y][x] = INF;
            } else if (grid[y][x] == 'S') {
                stores[scnt].x = x;
                stores[scnt].y = y;
                scnt++;
            } else if (grid[y][x] == '.') {
                cands[ccnt].x = x;
                cands[ccnt].y = y;
                candId[y][x] = ccnt;
                ccnt++;
            }
        }
    }

    /* Multi-source BFS from existing stores:
       computes nearest-store distance and unique owner / tie. */
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            if (grid[y][x] != '#') {
                dista[y][x] = INF;
                owner[y][x] = -1;
            }
        }
    }

    int head = 0, tail = 0;
    for (int i = 0; i < scnt; i++) {
        int x = stores[i].x, y = stores[i].y;
        dista[y][x] = 0;
        owner[y][x] = i;
        qx[tail] = x;
        qy[tail] = y;
        qid[tail] = i;
        tail++;
    }

    while (head < tail) {
        int x = qx[head];
        int y = qy[head];
        int id = qid[head];
        head++;

        int d = dista[y][x];
        const int *dx = (y & 1) ? dx_odd : dx_even;
        const int *dy = (y & 1) ? dy_odd : dy_even;

        for (int k = 0; k < 6; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (!inb(nx, ny) || grid[ny][nx] == '#') continue;

            if (dista[ny][nx] == INF) {
                dista[ny][nx] = d + 1;
                owner[ny][nx] = id;
                qx[tail] = nx;
                qy[tail] = ny;
                qid[tail] = id;
                tail++;
            } else if (dista[ny][nx] == d + 1 && owner[ny][nx] != id) {
                owner[ny][nx] = -1; /* tie */
            }
        }
    }

    /* Difference array by distance:
       For a cell with nearest existing-store distance d:
       a new store at distance t from this cell captures it iff t < d.
       So all candidates within radius d-1 from the cell gain +1.
       We BFS from each cell up to depth d-1 and add to candidates reached.
       Since this can be expensive in worst case, this solution targets
       moderate input sizes typical for this problem. */

    int *ans = (int *)calloc(ccnt, sizeof(int));
    int *vis = (int *)malloc(sizeof(int) * W * H);
    int visToken = 1;

    for (int sy = 0; sy < H; sy++) {
        for (int sx = 0; sx < W; sx++) {
            if (grid[sy][sx] == '#') continue;
            int limit = dista[sy][sx] - 1;
            if (limit < 0) continue; /* existing store cell */

            head = tail = 0;
            qx[tail] = sx;
            qy[tail] = sy;
            qid[tail] = 0; /* use as depth */
            tail++;

            vis[sy * W + sx] = visToken;

            while (head < tail) {
                int x = qx[head];
                int y = qy[head];
                int dep = qid[head];
                head++;

                int cid = candId[y][x];
                if (cid >= 0) ans[cid]++;

                if (dep == limit) continue;

                const int *dx = (y & 1) ? dx_odd : dx_even;
                const int *dy = (y & 1) ? dy_odd : dy_even;

                for (int k = 0; k < 6; k++) {
                    int nx = x + dx[k];
                    int ny = y + dy[k];
                    if (!inb(nx, ny) || grid[ny][nx] == '#') continue;
                    int idx = ny * W + nx;
                    if (vis[idx] == visToken) continue;
                    vis[idx] = visToken;
                    qx[tail] = nx;
                    qy[tail] = ny;
                    qid[tail] = dep + 1;
                    tail++;
                }
            }
            visToken++;
            if (visToken == INF) {
                memset(vis, 0, sizeof(int) * W * H);
                visToken = 1;
            }
        }
    }

    int best = 0;
    for (int i = 0; i < ccnt; i++) {
        if (ans[i] > best) best = ans[i];
    }

    printf("%d\n", best);

    free(ans);
    free(vis);
    return 0;
}

