    }

    // Store existing store positions
    vector<pair<int,int>> stores;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'S') {
                stores.push_back({i, j});
            }
        }
    }

    // For each block, find distance to nearest store
    const int INF = 1e9;
    vector<vector<int>> dist(H, vector<int>(W, INF));
    queue<pair<int,int>> q;

    for (auto [r, c] : stores) {
        dist[r][c] = 0;
        q.push({r, c});
    }

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        int d = dist[r][c];

        for (int k = 0; k < 6; k++) {
            int nr = r + dx[k];
            int nc = c + dy[k];
            if (nr >= 0 && nr < H && nc >= 0 && nc < W) {
                if (dist[nr][nc] > d + 1) {
                    dist[nr][nc] = d + 1;
                    q.push({nr, nc});
                }
            }
        }
    }

    // For each possible new store location (empty block), compute coverage
    int maxCovered = 0;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] != '.') continue; // Only consider empty blocks

            // BFS from this new store to find blocks it would cover
            vector<vector<int>> newDist(H, vector<int>(W, INF));
            queue<pair<int,int>> q2;
            newDist[i][j] = 0;
            q2.push({i, j});

            while (!q2.empty()) {
                auto [r, c] = q2.front();
                q2.pop();
                int d = newDist[r][c];

                for (int k = 0; k < 6; k++) {
                    int nr = r + dx[k];
                    int nc = c + dy[k];
                    if (nr >= 0 && nr < H && nc >= 0 && nc < W) {
                        if (newDist[nr][nc] > d + 1) {
                            newDist[nr][nc] = d + 1;
                            q2.push({nr, nc});
                        }
                    }
                }
            }

            // Count blocks where new store is strictly closer
            int covered = 0;
            for (int r = 0; r < H; r++) {
                for (int c = 0; c < W; c++) {
                    if (newDist[r][c] < dist[r][c]) {
                        covered++;
                    }
                }
            }

            maxCovered = max(maxCovered, covered);
        }
    }

    cout << maxCovered << "\n";

    return 0;
}

