public class Main {
    static int hexDist(int r1, int c1, int r2, int c2) {
        // Convert to cube coordinates (even-r offset)
        int x1 = c1 - (r1 - (r1 & 1)) / 2;
        int z1 = r1;
        int y1 = -x1 - z1;
        int x2 = c2 - (r2 - (r2 & 1)) / 2;
        int z2 = r2;
        int y2 = -x2 - z2;
        return (Math.abs(x1-x2) + Math.abs(y1-y2) + Math.abs(z1-z2)) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int R = sc.nextInt(), C = sc.nextInt();
        char[][] grid = new char[R][C];
        List<int[]> stores = new ArrayList<>();
        for (int r = 0; r < R; r++) {
            String line = sc.next();
            for (int c = 0; c < C; c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] == '1') stores.add(new int[]{r, c});
            }
        }
        int[][] minDist = new int[R][C];
        for (int[] d : minDist) Arrays.fill(d, Integer.MAX_VALUE);
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++)
                for (int[] s : stores)
                    minDist[r][c] = Math.min(minDist[r][c], hexDist(r, c, s[0], s[1]));
        int ans = 0;
        for (int nr = 0; nr < R; nr++) for (int nc = 0; nc < C; nc++) {
            if (grid[nr][nc] == '1') continue;
            int cnt = 0;
            for (int r = 0; r < R; r++) for (int c = 0; c < C; c++) {
                int d = hexDist(r, c, nr, nc);
                if (stores.isEmpty() || d < minDist[r][c]) cnt++;
            }
            ans = Math.max(ans, cnt);
        }
        System.out.println(ans);
    }
